window.CODE = Object.assign(window.CODE || {}, {"ch37/clinic_tools.py":"\"\"\"The helpdesk's read-only tool, written ONCE as a JSON schema and rendered for each cloud (cloud_tools.py).\"\"\"\nfrom cloud_tools import Tool\n\nDOCTORS = {   # synthetic data, the same clinic as Chapter 27\n    \"cardiology\": [{\"doctor\": \"Dr Mehta\", \"days\": \"Mon, Wed\"}, {\"doctor\": \"Dr Rao\", \"days\": \"Thu, Fri\"}],\n    \"orthopaedics\": [{\"doctor\": \"Dr Iyer\", \"days\": \"Tue, Thu\"}],\n    \"paediatrics\": [{\"doctor\": \"Dr Khan\", \"days\": \"Mon, Tue, Fri\"}],\n}\n\n\ndef find_doctor(specialty: str) -> dict:\n    found = DOCTORS.get(specialty.strip().lower())\n    return {\"specialty\": specialty, \"doctors\": found} if found else {\"specialty\": specialty, \"doctors\": [], \"note\": \"no such specialty at City Clinic\"}\n\n\nFIND_DOCTOR = Tool(\n    name=\"find_doctor\",\n    description=\"Look up which City Clinic doctors see patients in a specialty, and on which weekdays. Read-only.\",\n    schema={\"type\": \"object\",\n            \"properties\": {\"specialty\": {\"type\": \"string\", \"description\": \"cardiology, orthopaedics or paediatrics\"}},\n            \"required\": [\"specialty\"], \"additionalProperties\": False},\n    fn=find_doctor)\n","ch37/cloud_llm.py":"\"\"\"One chat() for the three big clouds, with the same return shape as llm.chat() from Chapter 5.\n\n    CLOUD_PROVIDER=bedrock | foundry | gemini        (default: bedrock)\n\nAmazon Bedrock          AWS_REGION (default ap-south-1)    BEDROCK_MODEL_ID  (required)\nMicrosoft Foundry       FOUNDRY_BASE_URL  FOUNDRY_MODEL (your deployment name)  FOUNDRY_API_KEY\nGemini on Google Cloud  GOOGLE_CLOUD_PROJECT + GOOGLE_CLOUD_LOCATION  GEMINI_MODEL   (Vertex-style)\n                        or just GEMINI_API_KEY + GEMINI_MODEL                       (developer API, for trying it out)\n\nThere is deliberately NO default model id. Ids differ per account, per region and per cloud, and they are\nretired every few months, so a default would be wrong for someone. A missing setting raises a clear error.\n\n    from cloud_llm import chat\n    r = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(r[\"text\"], r[\"input_tokens\"], r[\"output_tokens\"], r[\"model\"])\n\"\"\"\nimport os\n\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))\n\n\nclass CloudConfigError(RuntimeError):\n    \"\"\"A required setting is missing. The message names the setting.\"\"\"\n\n\ndef _need(name: str) -> str:\n    value = os.getenv(name)\n    if not value:\n        raise CloudConfigError(f\"set {name} (see the docstring of cloud_llm.py)\")\n    return value\n\n\ndef _result(text: str, input_tokens: int, output_tokens: int, model: str) -> dict:\n    return {\"text\": text or \"\", \"input_tokens\": int(input_tokens or 0), \"output_tokens\": int(output_tokens or 0), \"model\": model}\n\n\ndef _messages(user: str, history: list | None) -> list[dict]:\n    \"\"\"History is the usual [{'role': 'user'|'assistant', 'content': str}] list.\"\"\"\n    return list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\n# ----------------------------------------------------------------------------- Amazon Bedrock (Converse API)\ndef bedrock_client(region: str | None = None):\n    import boto3\n    from botocore.config import Config\n    return boto3.client(\"bedrock-runtime\", region_name=region or os.getenv(\"AWS_REGION\", \"ap-south-1\"),\n                        config=Config(read_timeout=TIMEOUT, retries={\"max_attempts\": RETRIES + 1, \"mode\": \"standard\"}))\n\n\ndef bedrock_chat(user, system=None, history=None, max_tokens=800, model_id=None, client=None) -> dict:\n    model_id = model_id or _need(\"BEDROCK_MODEL_ID\")\n    client = client or bedrock_client()\n    args = {\"modelId\": model_id,\n            \"messages\": [{\"role\": m[\"role\"], \"content\": [{\"text\": m[\"content\"]}]} for m in _messages(user, history)],\n            \"inferenceConfig\": {\"maxTokens\": max_tokens}}\n    if system:\n        args[\"system\"] = [{\"text\": system}]\n    r = client.converse(**args)\n    text = \"\".join(b[\"text\"] for b in r[\"output\"][\"message\"][\"content\"] if \"text\" in b)\n    return _result(text, r[\"usage\"][\"inputTokens\"], r[\"usage\"][\"outputTokens\"], model_id)\n\n\n# ----------------------------------------------------------------------------- Microsoft Foundry (OpenAI-compatible)\ndef foundry_client(base_url: str | None = None, api_key=None):\n    \"\"\"api_key may be a string, or a function that returns a fresh Microsoft Entra token each time it is called.\"\"\"\n    import openai\n    return openai.OpenAI(base_url=base_url or _need(\"FOUNDRY_BASE_URL\"), api_key=api_key or _need(\"FOUNDRY_API_KEY\"),\n                         timeout=TIMEOUT, max_retries=RETRIES)\n\n\ndef foundry_chat(user, system=None, history=None, max_tokens=800, deployment=None, client=None) -> dict:\n    deployment = deployment or _need(\"FOUNDRY_MODEL\")      # on Foundry/Azure the \"model\" is YOUR DEPLOYMENT'S NAME\n    client = client or foundry_client()\n    msgs = ([{\"role\": \"system\", \"content\": system}] if system else []) + _messages(user, history)\n    r = client.chat.completions.create(model=deployment, messages=msgs, max_completion_tokens=max_tokens)\n    return _result(r.choices[0].message.content, r.usage.prompt_tokens, r.usage.completion_tokens, deployment)\n\n\n# ----------------------------------------------------------------------------- Gemini (Google Cloud)\ndef gemini_client():\n    from google import genai\n    if os.getenv(\"GOOGLE_CLOUD_PROJECT\"):                    # Vertex-style: uses your Google Cloud login, in a region you choose\n        return genai.Client(vertexai=True, project=os.environ[\"GOOGLE_CLOUD_PROJECT\"], location=_need(\"GOOGLE_CLOUD_LOCATION\"))\n    return genai.Client()                                    # developer API: reads GEMINI_API_KEY\n\n\ndef gemini_chat(user, system=None, history=None, max_tokens=800, model=None, client=None) -> dict:\n    from google.genai import types\n    model = model or _need(\"GEMINI_MODEL\")\n    client = client or gemini_client()\n    contents = [types.Content(role=\"model\" if m[\"role\"] == \"assistant\" else \"user\", parts=[types.Part(text=m[\"content\"])])\n                for m in _messages(user, history)]\n    r = client.models.generate_content(model=model, contents=contents,\n                                       config=types.GenerateContentConfig(system_instruction=system, max_output_tokens=max_tokens))\n    u = r.usage_metadata\n    return _result(r.text, getattr(u, \"prompt_token_count\", 0), getattr(u, \"candidates_token_count\", 0), model)\n\n\n# ----------------------------------------------------------------------------- the router\nADAPTERS = {\"bedrock\": bedrock_chat, \"foundry\": foundry_chat, \"gemini\": gemini_chat}\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None, max_tokens: int = 800,\n         provider: str | None = None, **kwargs) -> dict:\n    provider = provider or os.getenv(\"CLOUD_PROVIDER\", \"bedrock\")\n    if provider not in ADAPTERS:\n        raise CloudConfigError(f\"CLOUD_PROVIDER must be one of {sorted(ADAPTERS)}, not {provider!r}\")\n    return ADAPTERS[provider](user, system=system, history=history, max_tokens=max_tokens, **kwargs)\n","ch37/cloud_tools.py":"\"\"\"Define a tool once; render it for Bedrock, Foundry (OpenAI-style) or Gemini; run the tool loop on two of them.\n\nThe three clouds spell the same idea three ways:\n    Bedrock Converse   toolConfig.tools[].toolSpec.inputSchema.json     -> model asks with a toolUse block, you answer with toolResult\n    OpenAI-style       tools[].function.parameters                      -> model asks with tool_calls,       you answer with role \"tool\"\n    Gemini             types.FunctionDeclaration(parameters_json_schema)\nThe loops are the Chapter 9 agent loop again, with a hard step limit (Chapter 21) so a confused model cannot loop forever.\n\"\"\"\nimport json\nfrom dataclasses import dataclass\nfrom typing import Callable\n\nMAX_STEPS = 5\n\n\nclass TooManySteps(RuntimeError):\n    pass\n\n\n@dataclass(frozen=True)\nclass Tool:\n    name: str\n    description: str\n    schema: dict                 # JSON Schema for the arguments\n    fn: Callable[..., dict]      # the Python function that does the work (read-only in our helpdesk)\n\n\n# ----------------------------------------------------------------------------- one definition, three renderings\ndef to_bedrock(t: Tool) -> dict:\n    return {\"toolSpec\": {\"name\": t.name, \"description\": t.description, \"inputSchema\": {\"json\": t.schema}}}\n\n\ndef to_openai(t: Tool) -> dict:\n    return {\"type\": \"function\", \"function\": {\"name\": t.name, \"description\": t.description, \"parameters\": t.schema}}\n\n\ndef to_gemini(t: Tool):\n    from google.genai import types\n    return types.Tool(function_declarations=[types.FunctionDeclaration(\n        name=t.name, description=t.description, parameters_json_schema=t.schema)])\n\n\n# ----------------------------------------------------------------------------- running a tool safely\ndef run_tool(tools: dict[str, Tool], name: str, args: dict) -> tuple[dict, bool]:\n    \"\"\"Returns (result, ok). A bad call from the model becomes an error RESULT, never a crash, so it can correct itself.\"\"\"\n    tool = tools.get(name)\n    if tool is None:\n        return {\"error\": f\"unknown tool {name!r}; available: {sorted(tools)}\"}, False\n    missing = [k for k in tool.schema.get(\"required\", []) if k not in args]\n    if missing:\n        return {\"error\": f\"missing arguments: {missing}\"}, False\n    extra = [k for k in args if k not in tool.schema.get(\"properties\", {})]\n    if extra and tool.schema.get(\"additionalProperties\") is False:\n        return {\"error\": f\"unexpected arguments: {extra}\"}, False\n    try:\n        return tool.fn(**args), True\n    except Exception as exc:                                  # the model sees a short message; details belong in your logs\n        return {\"error\": f\"{type(exc).__name__} while running {name}\"}, False\n\n\n# ----------------------------------------------------------------------------- Amazon Bedrock tool loop\ndef bedrock_agent(user: str, tools: list[Tool], system: str | None = None, client=None, model_id: str | None = None,\n                  max_steps: int = MAX_STEPS, max_tokens: int = 800) -> dict:\n    from cloud_llm import _need, bedrock_client\n    model_id = model_id or _need(\"BEDROCK_MODEL_ID\")\n    client = client or bedrock_client()\n    by_name = {t.name: t for t in tools}\n    messages = [{\"role\": \"user\", \"content\": [{\"text\": user}]}]\n    calls, tokens_in, tokens_out = [], 0, 0\n    for step in range(1, max_steps + 1):\n        args = {\"modelId\": model_id, \"messages\": messages, \"toolConfig\": {\"tools\": [to_bedrock(t) for t in tools]},\n                \"inferenceConfig\": {\"maxTokens\": max_tokens}}\n        if system:\n            args[\"system\"] = [{\"text\": system}]\n        r = client.converse(**args)\n        tokens_in += r[\"usage\"][\"inputTokens\"]\n        tokens_out += r[\"usage\"][\"outputTokens\"]\n        message = r[\"output\"][\"message\"]\n        messages.append(message)\n        if r[\"stopReason\"] != \"tool_use\":\n            text = \"\".join(b[\"text\"] for b in message[\"content\"] if \"text\" in b)\n            return {\"text\": text, \"tool_calls\": calls, \"steps\": step, \"input_tokens\": tokens_in, \"output_tokens\": tokens_out, \"model\": model_id}\n        results = []\n        for block in message[\"content\"]:\n            if \"toolUse\" in block:\n                use = block[\"toolUse\"]\n                out, ok = run_tool(by_name, use[\"name\"], use[\"input\"])\n                calls.append((use[\"name\"], use[\"input\"], ok))\n                results.append({\"toolResult\": {\"toolUseId\": use[\"toolUseId\"], \"content\": [{\"json\": out}],\n                                               \"status\": \"success\" if ok else \"error\"}})\n        messages.append({\"role\": \"user\", \"content\": results})\n    raise TooManySteps(f\"no final answer after {max_steps} model calls\")\n\n\n# ----------------------------------------------------------------------------- Foundry (OpenAI-style) tool loop\ndef foundry_agent(user: str, tools: list[Tool], system: str | None = None, client=None, deployment: str | None = None,\n                  max_steps: int = MAX_STEPS, max_tokens: int = 800) -> dict:\n    from cloud_llm import _need, foundry_client\n    deployment = deployment or _need(\"FOUNDRY_MODEL\")\n    client = client or foundry_client()\n    by_name = {t.name: t for t in tools}\n    messages = ([{\"role\": \"system\", \"content\": system}] if system else []) + [{\"role\": \"user\", \"content\": user}]\n    calls, tokens_in, tokens_out = [], 0, 0\n    for step in range(1, max_steps + 1):\n        r = client.chat.completions.create(model=deployment, messages=messages, tools=[to_openai(t) for t in tools],\n                                           max_completion_tokens=max_tokens)\n        tokens_in += r.usage.prompt_tokens\n        tokens_out += r.usage.completion_tokens\n        msg = r.choices[0].message\n        if not msg.tool_calls:\n            return {\"text\": msg.content or \"\", \"tool_calls\": calls, \"steps\": step, \"input_tokens\": tokens_in,\n                    \"output_tokens\": tokens_out, \"model\": deployment}\n        messages.append({\"role\": \"assistant\", \"content\": msg.content,\n                         \"tool_calls\": [{\"id\": c.id, \"type\": \"function\", \"function\": {\"name\": c.function.name, \"arguments\": c.function.arguments}}\n                                        for c in msg.tool_calls]})\n        for c in msg.tool_calls:\n            try:\n                args = json.loads(c.function.arguments or \"{}\")\n            except json.JSONDecodeError:\n                out, ok = {\"error\": \"arguments were not valid JSON\"}, False\n            else:\n                out, ok = run_tool(by_name, c.function.name, args)\n            calls.append((c.function.name, args if ok else c.function.arguments, ok))\n            messages.append({\"role\": \"tool\", \"tool_call_id\": c.id, \"content\": json.dumps(out)})\n    raise TooManySteps(f\"no final answer after {max_steps} model calls\")\n","ch37/demo_offline.py":"\"\"\"Runs every Chapter 37 idea with NO cloud account: AWS calls go to botocore's Stubber, OpenAI and Gemini calls to an\nin-memory fake server. Shows the request SHAPES and our code's behaviour, not a real cloud's answers.   OFFLINE=1 python demo_offline.py\"\"\"\nimport json\nimport os\n\nos.environ[\"OFFLINE\"] = \"1\"\nimport boto3\nimport httpx\nimport openai\nfrom botocore.stub import Stubber\nfrom google import genai\nfrom google.genai import types\n\nimport cloud_llm\nimport cloud_tools as T\nimport iam_policy\nimport lambda_handler\nimport residency\nfrom clinic_tools import FIND_DOCTOR\n\nprint(\"== 1. one chat(), three clouds (fake servers)\")\nbedrock = boto3.client(\"bedrock-runtime\", region_name=\"ap-south-1\", aws_access_key_id=\"x\", aws_secret_access_key=\"y\")\nstub = Stubber(bedrock)\nstub.add_response(\"converse\", {\"output\": {\"message\": {\"role\": \"assistant\", \"content\": [{\"text\": \"OPD runs 9 to 5.\"}]}}, \"stopReason\": \"end_turn\",\n                               \"usage\": {\"inputTokens\": 21, \"outputTokens\": 6, \"totalTokens\": 27}, \"metrics\": {\"latencyMs\": 1}})\nwith stub:\n    print(\"bedrock:\", cloud_llm.bedrock_chat(\"OPD timings?\", model_id=\"provider.model-v1\", client=bedrock))\noa = openai.OpenAI(base_url=\"https://my-resource.services.ai.azure.com/openai/v1\", api_key=\"k\", max_retries=0, http_client=httpx.Client(transport=httpx.MockTransport(\n    lambda r: httpx.Response(200, json={\"id\": \"c\", \"object\": \"chat.completion\", \"created\": 1, \"model\": \"m\", \"choices\": [{\"index\": 0, \"finish_reason\": \"stop\", \"message\": {\"role\": \"assistant\", \"content\": \"OPD runs 9 to 5.\"}}],\n                                        \"usage\": {\"prompt_tokens\": 21, \"completion_tokens\": 6, \"total_tokens\": 27}}))))\nprint(\"foundry:\", cloud_llm.foundry_chat(\"OPD timings?\", deployment=\"my-deployment\", client=oa))\ngem = genai.Client(api_key=\"k\", http_options=types.HttpOptions(httpx_client=httpx.Client(transport=httpx.MockTransport(\n    lambda r: httpx.Response(200, json={\"candidates\": [{\"content\": {\"role\": \"model\", \"parts\": [{\"text\": \"OPD runs 9 to 5.\"}]}, \"finishReason\": \"STOP\"}],\n                                        \"usageMetadata\": {\"promptTokenCount\": 21, \"candidatesTokenCount\": 6, \"totalTokenCount\": 27}})))))\nprint(\"gemini: \", cloud_llm.gemini_chat(\"OPD timings?\", model=\"gemini-test\", client=gem))\n\nprint(\"\\n== 2. the Bedrock tool loop (fake model asks for find_doctor, then answers)\")\nclient = boto3.client(\"bedrock-runtime\", region_name=\"ap-south-1\", aws_access_key_id=\"x\", aws_secret_access_key=\"y\")\nsent = []\nclient.meta.events.register(\"provide-client-params.bedrock-runtime.Converse\", lambda params, **kw: sent.append(json.loads(json.dumps(params))))\nstub = Stubber(client)\nstub.add_response(\"converse\", {\"output\": {\"message\": {\"role\": \"assistant\", \"content\": [{\"toolUse\": {\"toolUseId\": \"t1\", \"name\": \"find_doctor\", \"input\": {\"specialty\": \"cardiology\"}}}]}},\n                               \"stopReason\": \"tool_use\", \"usage\": {\"inputTokens\": 40, \"outputTokens\": 10, \"totalTokens\": 50}, \"metrics\": {\"latencyMs\": 1}})\nstub.add_response(\"converse\", {\"output\": {\"message\": {\"role\": \"assistant\", \"content\": [{\"text\": \"Dr Mehta sees cardiology patients on Mon and Wed; Dr Rao on Thu and Fri.\"}]}},\n                               \"stopReason\": \"end_turn\", \"usage\": {\"inputTokens\": 90, \"outputTokens\": 20, \"totalTokens\": 110}, \"metrics\": {\"latencyMs\": 1}})\nwith stub:\n    out = T.bedrock_agent(\"Which cardiologists are there?\", [FIND_DOCTOR], client=client, model_id=\"provider.model-v1\")\nprint({k: out[k] for k in (\"steps\", \"tool_calls\", \"input_tokens\", \"output_tokens\")})\nprint(\"what we sent back to the model:\", json.dumps(sent[1][\"messages\"][-1][\"content\"][0]))\ntry:\n    s2 = Stubber(client)\n    for i in range(3):\n        s2.add_response(\"converse\", {\"output\": {\"message\": {\"role\": \"assistant\", \"content\": [{\"toolUse\": {\"toolUseId\": f\"t{i}\", \"name\": \"find_doctor\", \"input\": {\"specialty\": \"cardiology\"}}}]}},\n                                     \"stopReason\": \"tool_use\", \"usage\": {\"inputTokens\": 1, \"outputTokens\": 1, \"totalTokens\": 2}, \"metrics\": {\"latencyMs\": 1}})\n    with s2:\n        T.bedrock_agent(\"loop\", [FIND_DOCTOR], client=client, model_id=\"m\", max_steps=3)\nexcept T.TooManySteps as e:\n    print(\"step limit:\", e)\n\nprint(\"\\n== 3. IAM policy for one Region, and the linter on a careless one\")\nprint(json.dumps(iam_policy.bedrock_single_region_policy(\"ap-south-1\", \"provider.model-v1\")[\"Statement\"][0], indent=1))\nprint(\"lint (ours):\", iam_policy.lint_policy(iam_policy.bedrock_single_region_policy(\"ap-south-1\", \"provider.model-v1\")))\ncareless = {\"Statement\": [{\"Sid\": \"Everything\", \"Effect\": \"Allow\", \"Action\": [\"bedrock:*\"], \"Resource\": \"*\"},\n                          {\"Sid\": \"AnyRegion\", \"Effect\": \"Allow\", \"Action\": [\"bedrock:InvokeModel\"], \"Resource\": \"arn:aws:bedrock:*::foundation-model/provider.model-v1\"}]}\nfor p in iam_policy.lint_policy(careless):\n    print(\" -\", p)\n\nprint(\"\\n== 4. data-residency rule: only one Region or a geography, only Mumbai/Hyderabad\")\nrule = dict(allowed_scopes=(\"region\", \"geography\"), allowed_regions=(\"ap-south-1\", \"ap-south-2\"))\nfor cloud, setting, region in [(\"aws\", \"provider.model-v1\", \"ap-south-1\"), (\"aws\", \"global.provider.model-v1\", \"ap-south-1\"),\n                               (\"aws\", \"provider.model-v1\", \"us-east-1\"), (\"azure\", \"DataZoneStandard\", None), (\"azure\", \"Standard\", None), (\"google\", \"global\", None)]:\n    print(f\"{cloud:6} {setting:26} {region or '-':10}\", residency.check(cloud, setting, region=region, **rule) or \"OK\")\n\nprint(\"\\n== 5. the same helpdesk as a Lambda function (stand-in model)\")\ndef event(msg):\n    return {\"version\": \"2.0\", \"rawPath\": \"/\", \"headers\": {}, \"requestContext\": {\"http\": {\"method\": \"POST\"}, \"requestId\": \"r-1\"}, \"body\": json.dumps({\"message\": msg}), \"isBase64Encoded\": False}\nfor msg in (\"Why is there an ECG charge on BILL-2291?\", \"I have severe chest pain\"):\n    r = lambda_handler.handler(event(msg))\n    print(r[\"statusCode\"], r[\"body\"][:120])\nfor f in (\"../ch27/traces.jsonl\",):\n    if os.path.exists(f):\n        os.remove(f)\n","ch37/deploy/bedrock-invoke-policy.json":"{\n  \"Version\": \"2012-10-17\",\n  \"Statement\": [\n    {\n      \"Sid\": \"AllowTheInferenceProfile\",\n      \"Effect\": \"Allow\",\n      \"Action\": [\n        \"bedrock:InvokeModel\"\n      ],\n      \"Resource\": [\n        \"arn:aws:bedrock:ap-south-1:123456789012:inference-profile/PREFIX.PROVIDER.MODEL-ID\"\n      ]\n    },\n    {\n      \"Sid\": \"AllowTheModelOnlyThroughThatProfile\",\n      \"Effect\": \"Allow\",\n      \"Action\": [\n        \"bedrock:InvokeModel\"\n      ],\n      \"Resource\": [\n        \"arn:aws:bedrock:ap-south-1::foundation-model/PROVIDER.MODEL-ID\",\n        \"arn:aws:bedrock:DESTINATION-REGION::foundation-model/PROVIDER.MODEL-ID\"\n      ],\n      \"Condition\": {\n        \"StringEquals\": {\n          \"bedrock:InferenceProfileArn\": \"arn:aws:bedrock:ap-south-1:123456789012:inference-profile/PREFIX.PROVIDER.MODEL-ID\"\n        }\n      }\n    }\n  ]\n}\n","ch37/deploy/lambda-template.yaml":"# The helpdesk as a Lambda function with a function URL. Validated with cfn-lint; NOT deployed (needs an AWS account).\n#   zip the ch27, ch33 and ch37 folders' .py files + dependencies, upload to S3, then deploy this template.\nAWSTemplateFormatVersion: \"2010-09-09\"\nDescription: City Clinic helpdesk on AWS Lambda, calling Bedrock with least privilege\n\nParameters:\n  CodeBucket: {Type: String, Description: S3 bucket holding the zip}\n  CodeKey: {Type: String, Description: S3 key of the zip}\n  BedrockModelId: {Type: String, Description: \"The exact model id you were granted, e.g. from the Bedrock console\"}\n  CallerRoleArn: {Type: String, Description: \"IAM role of YOUR backend, the only caller allowed to use the function URL\"}\n\nResources:\n  HelpdeskRole:\n    Type: AWS::IAM::Role\n    Properties:\n      AssumeRolePolicyDocument:\n        Version: \"2012-10-17\"\n        Statement:\n          - {Effect: Allow, Principal: {Service: lambda.amazonaws.com}, Action: \"sts:AssumeRole\"}\n      ManagedPolicyArns:\n        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole      # write logs, nothing else\n      Policies:\n        - PolicyName: InvokeOneModelInOneRegion\n          PolicyDocument:\n            Version: \"2012-10-17\"\n            Statement:\n              - Sid: AllowOneModelInOneRegion\n                Effect: Allow\n                Action: [\"bedrock:InvokeModel\"]                                 # Converse is governed by this action\n                Resource: !Sub \"arn:aws:bedrock:${AWS::Region}::foundation-model/${BedrockModelId}\"\n\n  HelpdeskFunction:\n    Type: AWS::Lambda::Function\n    Properties:\n      FunctionName: clinic-helpdesk\n      Runtime: python3.13\n      Handler: ch37.lambda_handler.handler\n      Role: !GetAtt HelpdeskRole.Arn\n      Code: {S3Bucket: !Ref CodeBucket, S3Key: !Ref CodeKey}\n      Timeout: 60                      # longer than the model call timeout (25 s), shorter than a patient's patience\n      MemorySize: 512\n      ReservedConcurrentExecutions: 5  # a ceiling on copies = a ceiling on cost during a flood (Chapter 32)\n      Environment:\n        Variables:\n          BEDROCK_MODEL_ID: !Ref BedrockModelId\n          MAX_MESSAGE_CHARS: \"2000\"\n\n  HelpdeskUrl:\n    Type: AWS::Lambda::Url\n    Properties:\n      TargetFunctionArn: !GetAtt HelpdeskFunction.Arn\n      AuthType: AWS_IAM                # callers must sign requests: no public URL, no API key to leak\n\n  AllowBackendToCallUrl:\n    Type: AWS::Lambda::Permission\n    Properties:\n      FunctionName: !Ref HelpdeskFunction\n      Action: lambda:InvokeFunctionUrl\n      Principal: !Ref CallerRoleArn\n      FunctionUrlAuthType: AWS_IAM\n\nOutputs:\n  FunctionUrl: {Value: !GetAtt HelpdeskUrl.FunctionUrl}\n","ch37/iam_policy.py":"\"\"\"Least-privilege AWS IAM policy for a Bedrock-calling agent, plus a linter for the mistakes that matter.\n\nThe shape follows AWS's documented pattern for cross-Region inference (docs: \"Geographic cross-Region inference\"):\n    1. allow InvokeModel on the inference profile (in your source Region, with your account id)\n    2. allow InvokeModel on the foundation model in the source Region AND in every destination Region of the profile,\n       but only when the call comes through THAT profile (condition key bedrock:InferenceProfileArn)\nConverse and ConverseStream are governed by the InvokeModel and InvokeModelWithResponseStream actions.\n\nNOT tested against real AWS (no account here): the JSON is checked by our tests and linter, and by cfn-lint inside\nthe CloudFormation template, but only IAM itself can say whether a policy works. Try it in a sandbox account.\n\"\"\"\nimport json\nimport sys\n\n\ndef bedrock_invoke_policy(account_id: str, source_region: str, profile_id: str, model_id: str,\n                          destination_regions: list[str], streaming: bool = False) -> dict:\n    actions = [\"bedrock:InvokeModel\"] + ([\"bedrock:InvokeModelWithResponseStream\"] if streaming else [])\n    profile_arn = f\"arn:aws:bedrock:{source_region}:{account_id}:inference-profile/{profile_id}\"\n    regions = [source_region] + [r for r in destination_regions if r != source_region]\n    return {\"Version\": \"2012-10-17\", \"Statement\": [\n        {\"Sid\": \"AllowTheInferenceProfile\", \"Effect\": \"Allow\", \"Action\": actions, \"Resource\": [profile_arn]},\n        {\"Sid\": \"AllowTheModelOnlyThroughThatProfile\", \"Effect\": \"Allow\", \"Action\": actions,\n         \"Resource\": [f\"arn:aws:bedrock:{r}::foundation-model/{model_id}\" for r in regions],\n         \"Condition\": {\"StringEquals\": {\"bedrock:InferenceProfileArn\": profile_arn}}}]}\n\n\ndef bedrock_single_region_policy(region: str, model_id: str, streaming: bool = False) -> dict:\n    \"\"\"No cross-Region profile: one model, one Region. The simplest policy, and the easiest to explain to an auditor.\"\"\"\n    actions = [\"bedrock:InvokeModel\"] + ([\"bedrock:InvokeModelWithResponseStream\"] if streaming else [])\n    return {\"Version\": \"2012-10-17\", \"Statement\": [\n        {\"Sid\": \"AllowOneModelInOneRegion\", \"Effect\": \"Allow\", \"Action\": actions,\n         \"Resource\": [f\"arn:aws:bedrock:{region}::foundation-model/{model_id}\"]}]}\n\n\ndef require_guardrail(policy: dict, guardrail_arn: str) -> dict:\n    \"\"\"Allow invocation ONLY when the call names this Bedrock guardrail (condition key bedrock:GuardrailIdentifier).\"\"\"\n    out = json.loads(json.dumps(policy))\n    for st in out[\"Statement\"]:\n        if st[\"Effect\"] == \"Allow\":\n            st.setdefault(\"Condition\", {}).setdefault(\"ArnEquals\", {})[\"bedrock:GuardrailIdentifier\"] = guardrail_arn\n    return out\n\n\ndef _as_list(x):\n    return x if isinstance(x, list) else [x]\n\n\ndef lint_policy(doc: dict) -> list[str]:\n    \"\"\"Problems found in an IAM policy document. An empty list means none of OUR rules fired, not that it is perfect.\"\"\"\n    problems = []\n    for i, st in enumerate(_as_list(doc.get(\"Statement\", []))):\n        sid = st.get(\"Sid\", f\"statement {i}\")\n        if st.get(\"Effect\") != \"Allow\":\n            continue\n        if \"NotAction\" in st or \"NotResource\" in st:\n            problems.append(f\"{sid}: Allow with NotAction/NotResource grants everything except a list; spell out what is allowed\")\n        for a in _as_list(st.get(\"Action\", [])):\n            if a == \"*\":\n                problems.append(f\"{sid}: Action '*' allows every action in every service\")\n            elif \"*\" in a:\n                problems.append(f\"{sid}: wildcard action {a!r}: list the exact actions the agent needs\")\n        for r in _as_list(st.get(\"Resource\", [])):\n            if r == \"*\":\n                problems.append(f\"{sid}: Resource '*' applies to everything\")\n            elif \"foundation-model/*\" in r or r.endswith(\".*\"):\n                problems.append(f\"{sid}: {r!r} covers a whole family of models: name the one model you use\")\n            elif r.startswith(\"arn:aws:bedrock:*\"):\n                problems.append(f\"{sid}: {r!r} allows any Region, which defeats a data-residency promise\")\n    return problems\n\n\nif __name__ == \"__main__\":      # python iam_policy.py ACCOUNT SOURCE_REGION PROFILE_ID MODEL_ID DEST1,DEST2\n    a = sys.argv[1:]\n    print(json.dumps(bedrock_invoke_policy(a[0], a[1], a[2], a[3], a[4].split(\",\")), indent=2))\n","ch37/lambda_handler.py":"\"\"\"The helpdesk as a serverless function: AWS Lambda behind a function URL (payload format 2.0).\n\nWhy serverless suits an agent that is used in bursts: you pay while it runs and nothing while it is idle, and AWS runs\nas many copies as traffic needs. What you give up: each copy is stateless (keep memory in a database, Chapter 10), a\ncopy that has been idle starts slowly (a 'cold start'), and one request may not run longer than the function timeout.\n\nCold-start rule: do the slow set-up (imports, loading documents, creating clients) at MODULE level, where it runs once per\ncopy; keep handler() small. Same safe-error and size rules as Chapter 36.\n\"\"\"\nimport base64\nimport hmac\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSAFE_ERROR = \"Sorry, something went wrong on our side. Please call the front desk on 1800-000-000.\"\nMAX_CHARS = int(os.getenv(\"MAX_MESSAGE_CHARS\", \"2000\"))\n_run = None\n\n\ndef default_run(message: str) -> str:\n    \"\"\"Chapter 33's guarded pipeline around the Chapter 27 helpdesk. Imported once, on first use, then reused.\"\"\"\n    global _run\n    if _run is None:\n        sys.path.insert(0, str(HERE.parent / \"ch33\"))\n        from guarded import guarded_run\n        _run = lambda m: guarded_run(m)[0]            # noqa: E731\n    return _run(message)\n\n\ndef _response(status: int, body: dict) -> dict:\n    return {\"statusCode\": status, \"headers\": {\"content-type\": \"application/json\"}, \"body\": json.dumps(body), \"isBase64Encoded\": False}\n\n\ndef handler(event: dict, context=None, run=None) -> dict:\n    run = run or default_run\n    if event.get(\"requestContext\", {}).get(\"http\", {}).get(\"method\") != \"POST\":\n        return _response(405, {\"error\": \"use POST\"})\n    keys = [k for k in os.getenv(\"API_KEYS\", \"\").split(\",\") if k]          # optional: the URL itself can require AWS_IAM signing instead\n    if keys:\n        sent = {k.lower(): v for k, v in (event.get(\"headers\") or {}).items()}.get(\"x-api-key\", \"\")\n        if not any(hmac.compare_digest(sent, k) for k in keys):\n            return _response(401, {\"error\": \"missing or wrong API key\"})\n    try:\n        raw = event.get(\"body\") or \"\"\n        if event.get(\"isBase64Encoded\"):\n            raw = base64.b64decode(raw).decode(\"utf-8\")\n        message = json.loads(raw)[\"message\"]\n        if not isinstance(message, str):\n            raise TypeError(\"message must be text\")\n    except (ValueError, KeyError, TypeError):\n        return _response(400, {\"error\": 'send JSON like {\"message\": \"...\"}'})\n    if len(message) > MAX_CHARS:\n        return _response(413, {\"error\": f\"message longer than {MAX_CHARS} characters\"})\n    try:\n        return _response(200, {\"reply\": run(message)})\n    except Exception:                                                       # details go to the logs (CloudWatch), never to the patient\n        print(json.dumps({\"event\": \"handler_error\", \"request_id\": event.get(\"requestContext\", {}).get(\"requestId\")}))\n        return _response(500, {\"reply\": SAFE_ERROR})\n","ch37/README.md":"# Chapter 37: cloud agent platforms\n\n    pip install -r requirements-cloud.txt -r ../requirements.txt\n    OFFLINE=1 pytest -q test_ch37.py        # 28 tests, no cloud account needed\n    OFFLINE=1 python demo_offline.py        # prints the outputs shown in the lessons\n\nTo try a real cloud, set the variables in the docstring of `cloud_llm.py` (`CLOUD_PROVIDER`, `BEDROCK_MODEL_ID` or `FOUNDRY_*` or `GEMINI_MODEL`, plus your cloud login) and call `chat()` once.\n\n**What the tests prove:** our requests have the right shape. AWS calls are checked by botocore's Stubber against AWS's own API model; the OpenAI and Gemini clients talk to an in-memory fake server (including a Vertex-style client routed to `asia-south1-aiplatform.googleapis.com`). The CloudFormation template passes `cfn-lint`.\n\n**Not run here (no cloud accounts):** any real Bedrock, Foundry or Gemini call; the IAM policies against real IAM; the Lambda deployment; AgentCore, Foundry Agent Service and Google's Agent Runtime. Product names in this chapter were read on 4 November 2026 and change often: check the vendors' pages.\n","ch37/requirements-cloud.txt":"# Chapter 37 (cloud platforms). The versions the tests were run with. boto3 pulls in botocore.\n# For the helpdesk itself (Chapters 27 and 33) also install ../requirements.txt\nboto3==1.43.123\ncfn-lint==1.59.0\ngoogle-genai==2.34.0\nhttpx==0.28.1\nopenai==3.43.0\npytest==9.2.0\n","ch37/residency.py":"\"\"\"Where may a prompt be processed? One rule, checked in code, for all three clouds.\n\nEach cloud lets you choose between 'stay in my Region/geography' and 'fastest and most available, anywhere'. The\nwords differ; the question is the same. We map each cloud's setting to one scale and let you set the rule once:\n\n    region        one named Region\n    geography     several Regions inside one geography (may include several countries)\n    data-zone     a zone such as US, EU or APAC (Azure data zones; Google multi-region 'us'/'eu')\n    global        any Region the provider chooses\n\nWhat the documentation says (read on 4 Nov 2026; check again, these change):\n  AWS    inference profile ids start with 'global.' (any commercial Region) or a geography prefix such as us. eu. apac. in.\n         (inside that geography); a plain model id is one Region. Prompts may be processed in other Regions of the profile.\n  Azure  deployment types: Global* (any Azure region), DataZone* (inside the data zone), Standard / ProvisionedManaged\n         (inside the Azure geography). 'DeveloperTier' has no residency guarantee.\n  Google a 'global' endpoint cannot tell you which Region processes a request; multi-region 'us'/'eu' keep ML processing in\n         that jurisdiction; Google's page also says endpoints in general 'don't guarantee data residency or in-region ML\n         processing', so read its data-residency page too.\nData AT REST is a separate question from where a prompt is PROCESSED. This file covers processing only.\n\"\"\"\nimport re\n\nSCOPES = (\"region\", \"geography\", \"data-zone\", \"global\")\n_AWS_GEO = re.compile(r\"^(us|eu|apac|in)\\.\")\n_AZURE = {\"GlobalStandard\": \"global\", \"GlobalProvisionedManaged\": \"global\", \"GlobalBatch\": \"global\", \"DeveloperTier\": \"global\",\n          \"DataZoneStandard\": \"data-zone\", \"DataZoneProvisionedManaged\": \"data-zone\", \"DataZoneBatch\": \"data-zone\",\n          \"Standard\": \"geography\", \"ProvisionedManaged\": \"geography\"}\n\n\ndef scope_for(cloud: str, setting: str) -> str:\n    \"\"\"Map a cloud-specific setting to the common scale. Unknown values raise, so a new option cannot slip through unchecked.\"\"\"\n    if cloud == \"aws\":                       # setting = the model id or inference profile id you pass to Converse (or its ARN)\n        ident = setting.rsplit(\"/\", 1)[-1]\n        parts = ident.split(\".\")\n        if len(parts) < 3:                   # 'provider.model': a plain foundation model, served from the one Region you call\n            return \"region\"\n        prefix = parts[0]                    # 'prefix.provider.model': an inference profile\n        if prefix == \"global\":\n            return \"global\"\n        if prefix in (\"us\", \"eu\", \"apac\", \"in\"):\n            return \"geography\"\n        raise ValueError(f\"unrecognised inference-profile prefix {prefix!r}: read what Regions it routes to before using it\")\n    if cloud == \"azure\":                     # setting = the deployment type (SKU)\n        if setting not in _AZURE:\n            raise ValueError(f\"unknown Azure deployment type {setting!r}: look it up before using it\")\n        return _AZURE[setting]\n    if cloud == \"google\":                    # setting = the location you create the client with\n        if setting == \"global\":\n            return \"global\"\n        if setting in (\"us\", \"eu\"):\n            return \"data-zone\"\n        return \"region\"\n    raise ValueError(f\"unknown cloud {cloud!r}\")\n\n\ndef check(cloud: str, setting: str, allowed_scopes=(\"region\", \"geography\"), region: str | None = None,\n          allowed_regions: tuple[str, ...] = ()) -> list[str]:\n    \"\"\"Problems with this setting under your rule. Run it at start-up and in CI.\n\n    `region` is the Region you CALL from. For a 'geography' or 'data-zone' setting the prompt may be processed in other\n    Regions of that geography, so allowed_regions does not cover them: read the profile's destination Regions too.\n    \"\"\"\n    scope = scope_for(cloud, setting)\n    problems = []\n    if scope not in allowed_scopes:\n        problems.append(f\"{cloud} setting {setting!r} has scope '{scope}', but only {list(allowed_scopes)} are allowed\")\n    if allowed_regions and region and region not in allowed_regions:\n        problems.append(f\"Region {region!r} is not in the allowed list {list(allowed_regions)}\")\n    return problems\n","ch37/test_ch37.py":"\"\"\"Tests for Chapter 37.   OFFLINE=1 pytest -q test_ch37.py        (needs: boto3, openai, google-genai, httpx, pytest; cfn-lint optional)\n\nEverything here runs with NO cloud account and NO network: the AWS SDK is exercised with botocore's Stubber (which checks\nevery request and response against AWS's own API model), and the OpenAI and Gemini SDKs talk to an in-memory fake server.\nThat proves our request SHAPES. It does not prove a real cloud accepts our credentials, models or permissions.\"\"\"\nimport base64\nimport copy\nimport json\nimport os\nimport shutil\nimport subprocess\nfrom pathlib import Path\n\nos.environ[\"OFFLINE\"] = \"1\"\nimport boto3  # noqa: E402\nimport httpx  # noqa: E402\nimport openai  # noqa: E402\nimport pytest  # noqa: E402\nfrom botocore.stub import Stubber  # noqa: E402\n\nimport cloud_llm  # noqa: E402\nimport iam_policy  # noqa: E402\nimport lambda_handler  # noqa: E402\nimport residency  # noqa: E402\nimport cloud_tools as T  # noqa: E402\nfrom clinic_tools import FIND_DOCTOR  # noqa: E402\n\nHERE = Path(__file__).parent\n\n\n# ----------------------------------------------------------------------------- Bedrock\ndef bedrock():\n    client = boto3.client(\"bedrock-runtime\", region_name=\"ap-south-1\", aws_access_key_id=\"x\", aws_secret_access_key=\"y\")\n    sent = []\n    client.meta.events.register(\"provide-client-params.bedrock-runtime.Converse\", lambda params, **kw: sent.append(copy.deepcopy(params)))\n    return client, Stubber(client), sent\n\n\ndef reply(content, stop=\"end_turn\", i=10, o=5):\n    return {\"output\": {\"message\": {\"role\": \"assistant\", \"content\": content}}, \"stopReason\": stop,\n            \"usage\": {\"inputTokens\": i, \"outputTokens\": o, \"totalTokens\": i + o}, \"metrics\": {\"latencyMs\": 1}}\n\n\ndef test_bedrock_chat_request_and_normalised_result():\n    client, stub, sent = bedrock()\n    stub.add_response(\"converse\", reply([{\"text\": \"OPD is 9 to 5.\"}], i=21, o=6))\n    with stub:\n        r = cloud_llm.bedrock_chat(\"OPD timings?\", system=\"You are the helpdesk.\", history=[{\"role\": \"user\", \"content\": \"hi\"}, {\"role\": \"assistant\", \"content\": \"hello\"}],\n                                   max_tokens=200, model_id=\"provider.model-v1\", client=client)\n    assert r == {\"text\": \"OPD is 9 to 5.\", \"input_tokens\": 21, \"output_tokens\": 6, \"model\": \"provider.model-v1\"}\n    assert sent[0] == {\"modelId\": \"provider.model-v1\", \"system\": [{\"text\": \"You are the helpdesk.\"}], \"inferenceConfig\": {\"maxTokens\": 200},\n                       \"messages\": [{\"role\": \"user\", \"content\": [{\"text\": \"hi\"}]}, {\"role\": \"assistant\", \"content\": [{\"text\": \"hello\"}]},\n                                    {\"role\": \"user\", \"content\": [{\"text\": \"OPD timings?\"}]}]}\n\n\ndef tool_use(id_, name, args):\n    return reply([{\"toolUse\": {\"toolUseId\": id_, \"name\": name, \"input\": args}}], stop=\"tool_use\")\n\n\ndef test_bedrock_tool_loop_runs_the_tool_and_returns_the_answer():\n    client, stub, sent = bedrock()\n    stub.add_response(\"converse\", tool_use(\"t1\", \"find_doctor\", {\"specialty\": \"cardiology\"}))\n    stub.add_response(\"converse\", reply([{\"text\": \"Dr Mehta (Mon, Wed) and Dr Rao (Thu, Fri).\"}], i=40, o=12))\n    with stub:\n        out = T.bedrock_agent(\"Which cardiologists are there?\", [FIND_DOCTOR], system=\"helpdesk\", client=client, model_id=\"m\")\n    assert out[\"text\"].startswith(\"Dr Mehta\") and out[\"steps\"] == 2 and out[\"tool_calls\"] == [(\"find_doctor\", {\"specialty\": \"cardiology\"}, True)]\n    assert out[\"input_tokens\"] == 50 and out[\"output_tokens\"] == 17          # both calls are counted\n    first, second = sent\n    assert first[\"toolConfig\"][\"tools\"][0][\"toolSpec\"][\"name\"] == \"find_doctor\"\n    result = second[\"messages\"][-1][\"content\"][0][\"toolResult\"]               # what we sent back to the model\n    assert result[\"toolUseId\"] == \"t1\" and result[\"status\"] == \"success\" and result[\"content\"][0][\"json\"][\"doctors\"][0][\"doctor\"] == \"Dr Mehta\"\n\n\ndef test_bedrock_bad_tool_call_becomes_an_error_result_not_a_crash():\n    client, stub, sent = bedrock()\n    stub.add_response(\"converse\", tool_use(\"t1\", \"delete_everything\", {}))\n    stub.add_response(\"converse\", reply([{\"text\": \"Sorry, I cannot do that.\"}]))\n    with stub:\n        out = T.bedrock_agent(\"hi\", [FIND_DOCTOR], client=client, model_id=\"m\")\n    result = sent[1][\"messages\"][-1][\"content\"][0][\"toolResult\"]\n    assert result[\"status\"] == \"error\" and \"unknown tool\" in result[\"content\"][0][\"json\"][\"error\"]\n    assert out[\"tool_calls\"][0][2] is False\n\n\ndef test_bedrock_loop_stops_after_the_step_limit():\n    client, stub, _ = bedrock()\n    for i in range(3):\n        stub.add_response(\"converse\", tool_use(f\"t{i}\", \"find_doctor\", {\"specialty\": \"cardiology\"}))\n    with stub, pytest.raises(T.TooManySteps):\n        T.bedrock_agent(\"loop forever\", [FIND_DOCTOR], client=client, model_id=\"m\", max_steps=3)\n\n\n# ----------------------------------------------------------------------------- Foundry (OpenAI-compatible)\ndef openai_client(handler, base_url=\"https://my-resource.services.ai.azure.com/openai/v1\"):\n    return openai.OpenAI(base_url=base_url, api_key=\"secret-key\", max_retries=0, http_client=httpx.Client(transport=httpx.MockTransport(handler)))\n\n\ndef completion(content=None, tool_calls=None, i=11, o=4):\n    msg = {\"role\": \"assistant\", \"content\": content}\n    if tool_calls:\n        msg[\"tool_calls\"] = tool_calls\n    return {\"id\": \"c1\", \"object\": \"chat.completion\", \"created\": 1, \"model\": \"my-deployment\",\n            \"choices\": [{\"index\": 0, \"finish_reason\": \"tool_calls\" if tool_calls else \"stop\", \"message\": msg}],\n            \"usage\": {\"prompt_tokens\": i, \"completion_tokens\": o, \"total_tokens\": i + o}}\n\n\ndef test_foundry_chat_uses_the_deployment_name_and_the_v1_path():\n    seen = []\n\n    def handler(request):\n        seen.append(request)\n        return httpx.Response(200, json=completion(\"OPD is 9 to 5.\", i=21, o=6))\n    r = cloud_llm.foundry_chat(\"OPD timings?\", system=\"helpdesk\", max_tokens=100, deployment=\"my-deployment\", client=openai_client(handler))\n    assert r == {\"text\": \"OPD is 9 to 5.\", \"input_tokens\": 21, \"output_tokens\": 6, \"model\": \"my-deployment\"}\n    req = seen[0]\n    assert req.url.path == \"/openai/v1/chat/completions\" and req.headers[\"authorization\"] == \"Bearer secret-key\"\n    body = json.loads(req.content)\n    assert body[\"model\"] == \"my-deployment\" and body[\"max_completion_tokens\"] == 100\n    assert body[\"messages\"][0] == {\"role\": \"system\", \"content\": \"helpdesk\"}\n\n\ndef test_foundry_tool_loop():\n    calls = []\n\n    def handler(request):\n        body = json.loads(request.content)\n        calls.append(body)\n        if len(calls) == 1:\n            return httpx.Response(200, json=completion(tool_calls=[{\"id\": \"call_1\", \"type\": \"function\",\n                                                                    \"function\": {\"name\": \"find_doctor\", \"arguments\": json.dumps({\"specialty\": \"paediatrics\"})}}]))\n        return httpx.Response(200, json=completion(\"Dr Khan sees children on Mon, Tue and Fri.\", i=30, o=9))\n    out = T.foundry_agent(\"Any paediatrician?\", [FIND_DOCTOR], client=openai_client(handler), deployment=\"my-deployment\")\n    assert out[\"text\"].startswith(\"Dr Khan\") and out[\"steps\"] == 2 and out[\"input_tokens\"] == 41\n    assert calls[0][\"tools\"][0][\"function\"][\"name\"] == \"find_doctor\"\n    tool_msg = calls[1][\"messages\"][-1]\n    assert tool_msg[\"role\"] == \"tool\" and tool_msg[\"tool_call_id\"] == \"call_1\" and \"Dr Khan\" in tool_msg[\"content\"]\n\n\ndef test_foundry_model_returning_broken_json_arguments_is_handled():\n    calls = []\n\n    def handler(request):\n        calls.append(json.loads(request.content))\n        if len(calls) == 1:\n            return httpx.Response(200, json=completion(tool_calls=[{\"id\": \"c\", \"type\": \"function\", \"function\": {\"name\": \"find_doctor\", \"arguments\": \"{not json\"}}]))\n        return httpx.Response(200, json=completion(\"Sorry, could you rephrase?\"))\n    out = T.foundry_agent(\"x\", [FIND_DOCTOR], client=openai_client(handler), deployment=\"d\")\n    assert out[\"tool_calls\"][0][2] is False and \"not valid JSON\" in calls[1][\"messages\"][-1][\"content\"]\n\n\n# ----------------------------------------------------------------------------- Gemini\ndef gemini_response(text, i=7, o=3):\n    return {\"candidates\": [{\"content\": {\"role\": \"model\", \"parts\": [{\"text\": text}]}, \"finishReason\": \"STOP\"}],\n            \"usageMetadata\": {\"promptTokenCount\": i, \"candidatesTokenCount\": o, \"totalTokenCount\": i + o}}\n\n\ndef test_gemini_developer_api_request_shape():\n    from google import genai\n    from google.genai import types\n    seen = []\n\n    def handler(request):\n        seen.append(request)\n        return httpx.Response(200, json=gemini_response(\"OPD is 9 to 5.\", i=21, o=6))\n    client = genai.Client(api_key=\"k\", http_options=types.HttpOptions(httpx_client=httpx.Client(transport=httpx.MockTransport(handler))))\n    r = cloud_llm.gemini_chat(\"OPD timings?\", system=\"helpdesk\", history=[{\"role\": \"assistant\", \"content\": \"hello\"}], max_tokens=64, model=\"gemini-test\", client=client)\n    assert r == {\"text\": \"OPD is 9 to 5.\", \"input_tokens\": 21, \"output_tokens\": 6, \"model\": \"gemini-test\"}\n    assert seen[0].url.path.endswith(\"models/gemini-test:generateContent\")\n    body = json.loads(seen[0].content)\n    assert body[\"generationConfig\"][\"maxOutputTokens\"] == 64 and body[\"systemInstruction\"][\"parts\"][0][\"text\"] == \"helpdesk\"\n    assert [c[\"role\"] for c in body[\"contents\"]] == [\"model\", \"user\"]          # 'assistant' is called 'model' on Gemini\n\n\ndef test_gemini_vertex_style_client_routes_to_the_regional_endpoint():\n    from google import genai\n    from google.oauth2.credentials import Credentials\n    from google.genai import types\n    seen = []\n\n    def handler(request):\n        seen.append(request)\n        return httpx.Response(200, json=gemini_response(\"ok\"))\n    client = genai.Client(vertexai=True, project=\"my-project\", location=\"asia-south1\", credentials=Credentials(token=\"fake-token-for-tests\"),\n                          http_options=types.HttpOptions(httpx_client=httpx.Client(transport=httpx.MockTransport(handler))))\n    cloud_llm.gemini_chat(\"hi\", model=\"gemini-test\", client=client)\n    url = seen[0].url\n    assert url.host == \"asia-south1-aiplatform.googleapis.com\"\n    assert \"projects/my-project/locations/asia-south1\" in url.path and url.path.endswith(\"models/gemini-test:generateContent\")\n\n\ndef test_gemini_tool_rendering_keeps_the_json_schema():\n    tool = T.to_gemini(FIND_DOCTOR)\n    decl = tool.function_declarations[0]\n    assert decl.name == \"find_doctor\" and decl.parameters_json_schema == FIND_DOCTOR.schema\n\n\n# ----------------------------------------------------------------------------- the common contract\ndef test_all_three_clouds_return_the_same_shape():\n    client, stub, _ = bedrock()\n    stub.add_response(\"converse\", reply([{\"text\": \"a\"}]))\n    with stub:\n        a = cloud_llm.bedrock_chat(\"q\", model_id=\"m\", client=client)\n    b = cloud_llm.foundry_chat(\"q\", deployment=\"d\", client=openai_client(lambda r: httpx.Response(200, json=completion(\"b\"))))\n    from google import genai\n    from google.genai import types\n    c = cloud_llm.gemini_chat(\"q\", model=\"g\", client=genai.Client(api_key=\"k\", http_options=types.HttpOptions(\n        httpx_client=httpx.Client(transport=httpx.MockTransport(lambda r: httpx.Response(200, json=gemini_response(\"c\")))))))\n    for r in (a, b, c):\n        assert set(r) == {\"text\", \"input_tokens\", \"output_tokens\", \"model\"} and isinstance(r[\"input_tokens\"], int) and isinstance(r[\"text\"], str)\n\n\ndef test_tool_renderings_carry_the_same_schema():\n    assert T.to_bedrock(FIND_DOCTOR)[\"toolSpec\"][\"inputSchema\"][\"json\"] == FIND_DOCTOR.schema\n    assert T.to_openai(FIND_DOCTOR)[\"function\"][\"parameters\"] == FIND_DOCTOR.schema\n\n\ndef test_missing_settings_name_the_setting(monkeypatch):\n    for name in (\"BEDROCK_MODEL_ID\", \"FOUNDRY_MODEL\", \"GEMINI_MODEL\", \"FOUNDRY_BASE_URL\", \"GOOGLE_CLOUD_PROJECT\"):\n        monkeypatch.delenv(name, raising=False)\n    with pytest.raises(cloud_llm.CloudConfigError, match=\"BEDROCK_MODEL_ID\"):\n        cloud_llm.bedrock_chat(\"q\", client=object())\n    with pytest.raises(cloud_llm.CloudConfigError, match=\"FOUNDRY_MODEL\"):\n        cloud_llm.foundry_chat(\"q\", client=object())\n    with pytest.raises(cloud_llm.CloudConfigError, match=\"GEMINI_MODEL\"):\n        cloud_llm.gemini_chat(\"q\", client=object())\n    with pytest.raises(cloud_llm.CloudConfigError, match=\"CLOUD_PROVIDER\"):\n        cloud_llm.chat(\"q\", provider=\"nonsense\")\n\n\ndef test_tool_argument_checks():\n    assert T.run_tool({\"find_doctor\": FIND_DOCTOR}, \"find_doctor\", {})[1] is False\n    assert \"unexpected\" in T.run_tool({\"find_doctor\": FIND_DOCTOR}, \"find_doctor\", {\"specialty\": \"cardiology\", \"evil\": 1})[0][\"error\"]\n    boom = T.Tool(\"boom\", \"x\", {\"type\": \"object\", \"properties\": {}}, lambda: 1 / 0)\n    out, ok = T.run_tool({\"boom\": boom}, \"boom\", {})\n    assert ok is False and out == {\"error\": \"ZeroDivisionError while running boom\"}          # no traceback, no internals\n\n\n# ----------------------------------------------------------------------------- IAM\nARGS = dict(account_id=\"123456789012\", source_region=\"ap-south-1\", profile_id=\"apac.provider.model-v1\", model_id=\"provider.model-v1\",\n            destination_regions=[\"ap-south-1\", \"ap-south-2\"])\n\n\ndef test_generated_policy_follows_the_documented_three_part_pattern():\n    p = iam_policy.bedrock_invoke_policy(**ARGS)\n    profile, model = p[\"Statement\"]\n    assert profile[\"Resource\"] == [\"arn:aws:bedrock:ap-south-1:123456789012:inference-profile/apac.provider.model-v1\"]\n    assert model[\"Resource\"] == [\"arn:aws:bedrock:ap-south-1::foundation-model/provider.model-v1\", \"arn:aws:bedrock:ap-south-2::foundation-model/provider.model-v1\"]\n    assert model[\"Condition\"] == {\"StringEquals\": {\"bedrock:InferenceProfileArn\": profile[\"Resource\"][0]}}\n    assert profile[\"Action\"] == [\"bedrock:InvokeModel\"]\n    assert iam_policy.lint_policy(p) == []\n    assert \"bedrock:InvokeModelWithResponseStream\" in iam_policy.bedrock_invoke_policy(**ARGS, streaming=True)[\"Statement\"][0][\"Action\"]\n\n\ndef test_single_region_policy_is_clean():\n    assert iam_policy.lint_policy(iam_policy.bedrock_single_region_policy(\"ap-south-1\", \"provider.model-v1\")) == []\n\n\ndef test_policy_linter_catches_the_classic_mistakes():\n    bad = {\"Version\": \"2012-10-17\", \"Statement\": [\n        {\"Sid\": \"A\", \"Effect\": \"Allow\", \"Action\": \"*\", \"Resource\": \"*\"},\n        {\"Sid\": \"B\", \"Effect\": \"Allow\", \"Action\": [\"bedrock:*\"], \"Resource\": \"arn:aws:bedrock:ap-south-1::foundation-model/*\"},\n        {\"Sid\": \"C\", \"Effect\": \"Allow\", \"Action\": [\"bedrock:InvokeModel\"], \"Resource\": \"arn:aws:bedrock:*::foundation-model/provider.model-v1\"},\n        {\"Sid\": \"D\", \"Effect\": \"Allow\", \"NotAction\": [\"iam:*\"], \"Resource\": \"arn:aws:bedrock:ap-south-1::foundation-model/anthropic.*\"},\n        {\"Sid\": \"E\", \"Effect\": \"Deny\", \"Action\": \"*\", \"Resource\": \"*\"}]}\n    text = \"\\n\".join(iam_policy.lint_policy(bad))\n    for needle in (\"A: Action '*'\", \"A: Resource '*'\", \"B: wildcard action 'bedrock:*'\", \"B: 'arn:aws:bedrock:ap-south-1::foundation-model/*'\",\n                   \"C: 'arn:aws:bedrock:*::foundation-model/provider.model-v1' allows any Region\", \"D: Allow with NotAction\", \"D: 'arn:aws:bedrock:ap-south-1::foundation-model/anthropic.*'\"):\n        assert needle in text, needle\n    assert \"E:\" not in text                        # a Deny of everything is fine\n\n\ndef test_require_guardrail_adds_the_condition_without_changing_the_original():\n    original = iam_policy.bedrock_single_region_policy(\"ap-south-1\", \"provider.model-v1\")\n    before = json.dumps(original)\n    g = iam_policy.require_guardrail(original, \"arn:aws:bedrock:ap-south-1:123456789012:guardrail/abc123:1\")\n    assert g[\"Statement\"][0][\"Condition\"] == {\"ArnEquals\": {\"bedrock:GuardrailIdentifier\": \"arn:aws:bedrock:ap-south-1:123456789012:guardrail/abc123:1\"}}\n    assert json.dumps(original) == before\n\n\ndef test_policy_file_in_deploy_is_what_the_generator_makes():\n    on_disk = json.loads((HERE / \"deploy\" / \"bedrock-invoke-policy.json\").read_text())\n    assert on_disk == iam_policy.bedrock_invoke_policy(\"123456789012\", \"ap-south-1\", \"PREFIX.PROVIDER.MODEL-ID\", \"PROVIDER.MODEL-ID\", [\"ap-south-1\", \"DESTINATION-REGION\"])\n\n\n@pytest.mark.skipif(shutil.which(\"cfn-lint\") is None and not (Path(os.sys.executable).parent / \"cfn-lint\").exists(), reason=\"cfn-lint not installed\")\ndef test_cloudformation_template_passes_cfn_lint():\n    exe = shutil.which(\"cfn-lint\") or str(Path(os.sys.executable).parent / \"cfn-lint\")\n    r = subprocess.run([exe, str(HERE / \"deploy\" / \"lambda-template.yaml\")], capture_output=True, text=True)\n    assert r.returncode == 0, r.stdout + r.stderr\n\n\n# ----------------------------------------------------------------------------- residency\ndef test_scopes_for_each_cloud():\n    s = residency.scope_for\n    assert s(\"aws\", \"provider.model-v1\") == \"region\" and s(\"aws\", \"apac.provider.model-v1\") == \"geography\" and s(\"aws\", \"global.provider.model-v1\") == \"global\"\n    assert s(\"aws\", \"arn:aws:bedrock:ap-south-1:123456789012:inference-profile/global.provider.model-v1\") == \"global\"\n    assert (s(\"azure\", \"Standard\"), s(\"azure\", \"DataZoneStandard\"), s(\"azure\", \"GlobalStandard\"), s(\"azure\", \"DeveloperTier\")) == (\"geography\", \"data-zone\", \"global\", \"global\")\n    assert (s(\"google\", \"asia-south1\"), s(\"google\", \"eu\"), s(\"google\", \"global\")) == (\"region\", \"data-zone\", \"global\")\n\n\ndef test_unknown_options_are_refused_not_guessed():\n    with pytest.raises(ValueError, match=\"prefix 'jp'\"):\n        residency.scope_for(\"aws\", \"jp.provider.model-v1\")\n    with pytest.raises(ValueError, match=\"unknown Azure deployment type\"):\n        residency.scope_for(\"azure\", \"SuperStandard\")\n    with pytest.raises(ValueError):\n        residency.scope_for(\"oracle\", \"x\")\n\n\ndef test_the_clinic_rule():\n    ok = residency.check(\"aws\", \"provider.model-v1\", region=\"ap-south-1\", allowed_regions=(\"ap-south-1\", \"ap-south-2\"))\n    assert ok == []\n    problems = residency.check(\"aws\", \"global.provider.model-v1\", region=\"us-east-1\", allowed_regions=(\"ap-south-1\", \"ap-south-2\"))\n    assert len(problems) == 2 and \"scope 'global'\" in problems[0] and \"us-east-1\" in problems[1]\n    assert residency.check(\"azure\", \"GlobalStandard\")[0].startswith(\"azure setting 'GlobalStandard' has scope 'global'\")\n    assert residency.check(\"google\", \"asia-south1\") == []\n\n\n# ----------------------------------------------------------------------------- Lambda handler (format version 2.0 events)\ndef event(method=\"POST\", body='{\"message\": \"hi\"}', headers=None, b64=False):\n    if b64:\n        body = base64.b64encode(body.encode()).decode()\n    return {\"version\": \"2.0\", \"routeKey\": \"$default\", \"rawPath\": \"/\", \"rawQueryString\": \"\", \"headers\": headers or {},\n            \"requestContext\": {\"http\": {\"method\": method, \"path\": \"/\", \"protocol\": \"HTTP/1.1\", \"sourceIp\": \"1.2.3.4\", \"userAgent\": \"t\"}, \"requestId\": \"r-1\"},\n            \"body\": body, \"isBase64Encoded\": b64}\n\n\ndef test_handler_happy_path_and_response_format():\n    r = lambda_handler.handler(event(), run=lambda m: f\"echo: {m}\")\n    assert r[\"statusCode\"] == 200 and r[\"headers\"][\"content-type\"] == \"application/json\" and r[\"isBase64Encoded\"] is False\n    assert json.loads(r[\"body\"]) == {\"reply\": \"echo: hi\"}\n\n\ndef test_handler_rejects_bad_requests():\n    run = lambda m: \"x\"            # noqa: E731\n    assert lambda_handler.handler(event(method=\"GET\"), run=run)[\"statusCode\"] == 405\n    assert lambda_handler.handler(event(body=\"not json\"), run=run)[\"statusCode\"] == 400\n    assert lambda_handler.handler(event(body='{\"message\": 5}'), run=run)[\"statusCode\"] == 400\n    assert lambda_handler.handler(event(body='{\"other\": \"x\"}'), run=run)[\"statusCode\"] == 400\n    assert lambda_handler.handler(event(body=json.dumps({\"message\": \"x\" * 5000})), run=run)[\"statusCode\"] == 413\n    assert json.loads(lambda_handler.handler(event(b64=True), run=run)[\"body\"]) == {\"reply\": \"x\"}\n\n\ndef test_handler_api_key_when_configured(monkeypatch):\n    monkeypatch.setenv(\"API_KEYS\", \"good-key,other-key\")\n    run = lambda m: \"x\"            # noqa: E731\n    assert lambda_handler.handler(event(), run=run)[\"statusCode\"] == 401\n    assert lambda_handler.handler(event(headers={\"X-Api-Key\": \"wrong\"}), run=run)[\"statusCode\"] == 401\n    assert lambda_handler.handler(event(headers={\"X-Api-Key\": \"other-key\"}), run=run)[\"statusCode\"] == 200      # header names are case-insensitive\n\n\ndef test_handler_errors_are_safe(capsys):\n    def boom(m):\n        raise RuntimeError(\"password=hunter2 in db://internal\")\n    r = lambda_handler.handler(event(), run=boom)\n    assert r[\"statusCode\"] == 500 and json.loads(r[\"body\"]) == {\"reply\": lambda_handler.SAFE_ERROR}\n    assert \"hunter2\" not in r[\"body\"] and \"hunter2\" not in capsys.readouterr().out          # not in the response, not in the log either\n\n\ndef test_real_helpdesk_through_the_handler():\n    for msg, needle in ((\"Why is there an ECG charge on BILL-2291?\", \"BILL-2291\"), (\"I have severe chest pain\", \"108\")):\n        r = lambda_handler.handler(event(body=json.dumps({\"message\": msg})))\n        assert r[\"statusCode\"] == 200 and needle in json.loads(r[\"body\"])[\"reply\"]\n    (HERE.parent / \"ch27\" / \"traces.jsonl\").unlink(missing_ok=True)\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
